package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.TypedFields.require;
import java.sql.SQLException;
import java.util.*;
import org.apache.commons.codec.digest.DigestUtils;
/** Independent review is bound to current content, publication, policy and both accounts. */
final class KnowledgeReviews {
 private KnowledgeReviews() {}
 static Map<String,Object> policy(Store.Db db,String id)throws SQLException {var row=db.one("SELECT * FROM os_knowledge_policy WHERE article_id=?",id);return row==null?map("article_id",id,"revision",0,"reviewer_id",""):row;}
 static Map<String,Object> authority(Store.Db db,String id)throws SQLException {return db.one("SELECT user_id,auth_revision FROM os_user WHERE user_id=? AND active=1 AND role='admin' AND password_reset_required=0",id);}
 static String proof(Store.Db db,String id,String requester)throws SQLException {var policy=policy(db,id);return DigestUtils.sha256Hex(JSON.writeValueAsString(map("article",Service.readRecord(db,"kb_knowledge",id),"schema",Service.schema(db,"kb_knowledge"),"access",RecordAccess.status(db,id),"latest",db.one("SELECT * FROM os_publication WHERE article_id=? ORDER BY version DESC LIMIT 1",id),"policy",policy,"requester",authority(db,requester),"reviewer",authority(db,policy.get("reviewer_id").toString()))));}
 static Map<String,Object> page(Store.Db db,String id)throws SQLException {
  var draft=KnowledgeDrafts.review(db,id,Map.of());var policy=policy(db,id);var request=db.one("SELECT * FROM os_knowledge_review WHERE article_id=?",id);if(request==null)request=map();boolean current=!request.isEmpty() && request.get("proof").equals(proof(db,id,request.get("requester_id").toString()));String token=DigestUtils.sha256Hex(JSON.writeValueAsString(map("draft",draft.get("review"),"policy",policy,"request",request,"reviewer",authority(db,policy.get("reviewer_id").toString()))));request.remove("proof");return map("article_id",id,"draft",draft.get("draft"),"latest",draft.get("latest"),"policy",policy,"request",request,"current",current,"review",token,"can_decide",current && request.get("status").equals("pending") && policy.get("reviewer_id").equals(db.viewerId),"can_apply",current && request.get("status").equals("approved") && request.get("requester_id").equals(db.viewerId),"reviewer_name",db.one("SELECT COALESCE((SELECT name FROM os_user WHERE user_id=?),'Unavailable reviewer') AS name",policy.get("reviewer_id")).get("name"),"reviewers",db.all("SELECT user_id,name FROM os_user WHERE active=1 AND role='admin' AND password_reset_required=0 ORDER BY name LIMIT 100"));
 }
 static Map<String,Object> act(Store.Db db,String id,Object input)throws SQLException {
  if(db.postgres)db.all("SELECT pg_advisory_xact_lock(18439,4)");var body=object(input);String operation=WorkJobs.text(body.get("operation"),20);var keys=new HashSet<>(Set.of("operation","review","confirm"));switch(operation){case "configure"->keys.add("reviewer_id");case "submit"->keys.add("intent");case "approve","reject"->keys.add("reason");case "apply"->{}default->throw new Failure(400,"Choose configure, submit, approve, reject or apply");}require(body.keySet().equals(keys) && Boolean.TRUE.equals(body.get("confirm")),"Provide the action fields and confirm the current review");var view=page(db,id);if(!view.get("review").equals(body.get("review")))throw new Failure(409,"Knowledge review changed; reload it");var policy=object(view.get("policy"));var request=object(view.get("request"));
  switch(operation){
   case "configure"->{require(body.get("reviewer_id") instanceof String,"Reviewer must be an account ID or empty");String reviewer=body.get("reviewer_id").toString();require(reviewer.isEmpty() || authority(db,reviewer)!=null,"Choose an active administrator without a required password reset");int revision=((Number)policy.get("revision")).intValue()+1;db.update("DELETE FROM os_knowledge_policy WHERE article_id=?",id);db.update("INSERT INTO os_knowledge_policy(article_id,revision,reviewer_id) VALUES(?,?,?)",id,revision,reviewer);db.update("DELETE FROM os_knowledge_review WHERE article_id=?",id);}
   case "submit"->{String intent=WorkJobs.text(body.get("intent"),20);require(Set.of("publish","retire").contains(intent),"Choose publish or retire");String reviewer=policy.get("reviewer_id").toString();require(authority(db,reviewer)!=null && authority(db,db.viewerId)!=null,"Configure an active independent reviewer first");require(!reviewer.equals(db.viewerId),"The requester cannot review their own action");if(intent.equals("publish")){require(RecordAccess.status(db,id).get("visibility").equals("workspace"),"Publication requires workspace visibility");var draft=object(view.get("draft"));WorkJobs.text(draft.get("short_description"),1000);WorkJobs.text(draft.get("text"),100000);}else{var latest=object(view.get("latest"));require(!latest.isEmpty() && latest.get("retired").toString().equals("0"),"Retirement requires a live publication");}String proof=proof(db,id,db.viewerId);db.update("DELETE FROM os_knowledge_review WHERE article_id=?",id);db.update("INSERT INTO os_knowledge_review(article_id,request_id,requester_id,intent,proof,status,reason,created) VALUES(?,?,?,?,?,'pending','',?)",id,Values.id(),db.viewerId,intent,proof,now());}
   case "approve","reject"->{if(!Boolean.TRUE.equals(view.get("can_decide")))throw new Failure(409,"Only the current independent reviewer can decide a current pending request");String reason=WorkJobs.text(body.get("reason"),2000);db.update("UPDATE os_knowledge_review SET status=?,reason=? WHERE article_id=?",operation.equals("approve")?"approved":"rejected",reason,id);}
   default->{if(!Boolean.TRUE.equals(view.get("can_apply")))throw new Failure(409,"Only the original requester can apply a current approved action");if(request.get("intent").equals("publish"))PublishedKnowledge.publish(db,db.viewerId,id);else PublishedKnowledge.retire(db,db.viewerId,id);}
  }
  SecurityEvents.record(db,db.viewerId,db.viewerId,"knowledge.review_"+operation,map("article_id",id));return page(db,id);
 }
 static void consume(Store.Db db,String actor,String id,String intent)throws SQLException {
  if(policy(db,id).get("reviewer_id").toString().isEmpty())return;
  var row=db.one("SELECT * FROM os_knowledge_review WHERE article_id=? AND requester_id=? AND intent=? AND status='approved'",id,actor,intent);if(row==null || !row.get("proof").equals(proof(db,id,actor)))throw new Failure(409,"Current independent approval is required; open the knowledge review");db.update("UPDATE os_knowledge_review SET status='applied' WHERE article_id=?",id);SecurityEvents.record(db,actor,actor,"knowledge.review_applied",map("article_id",id,"request_id",row.get("request_id"),"intent",intent));
 }
 static void instantRestore(Store.Db db,String id)throws SQLException {require(policy(db,id).get("reviewer_id").toString().isEmpty(),"Recover the historical version into a draft and submit it for review");}
}
